753		<script>
754			const themeToggle = document.getElementById('theme-toggle');
755			const htmlElement = document.documentElement;
756			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
757	
758			const themeColors = { light: '#ffffff', dark: '#121212' };
759			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
760			themeColorMetas.forEach((meta) => {
761				meta.dataset.defaultContent = meta.content;
762			});
763	
764			const updateThemeUI = () => {
765				const forced = htmlElement.dataset.theme;
766				const isDark = forced ? forced === 'dark' : prefersDark.matches;
767				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
768				themeToggle.textContent = isDark ? '☀️' : '🌙';
769				themeToggle.setAttribute('aria-label', label);
770				themeToggle.title = label;
771				themeColorMetas.forEach((meta) => {
772					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
773				});
774			};
775	
776			if (themeToggle) {
777				themeToggle.hidden = false;
778				updateThemeUI();
779	
780				themeToggle.addEventListener('click', () => {
781					const systemTheme = prefersDark.matches ? 'dark' : 'light';
782					const current = htmlElement.dataset.theme || systemTheme;
783					const next = current === 'dark' ? 'light' : 'dark';
784					// Choosing the system theme clears the override so the page follows the OS again.
785					try {
786						if (next === systemTheme) {
787							delete htmlElement.dataset.theme;
788							localStorage.removeItem('theme');
789						} else {
790							htmlElement.dataset.theme = next;
791							localStorage.setItem('theme', next);
792						}
793					} catch {}
794					updateThemeUI();
795				});
796	
797				prefersDark.addEventListener('change', () => {
798					if (!htmlElement.dataset.theme) {
799						updateThemeUI();
800					}
801				});
802	
803				// Keep other open tabs in step with the choice made in this one.
804				window.addEventListener('storage', (event) => {
805					if (event.key !== null && event.key !== 'theme') {
806						return;
807					}
808					if (event.newValue === 'light' || event.newValue === 'dark') {
809						htmlElement.dataset.theme = event.newValue;
810					} else {
811						delete htmlElement.dataset.theme;
812					}
813					updateThemeUI();
814				});
815			}
816	
817			const copyrightYear = document.getElementById('copyright-year');
818			if (copyrightYear) {
819				copyrightYear.textContent = String(new Date().getFullYear());
820			}
821	
822			const messages = [
823				"This update was announced to screen readers!",
824				"Dynamic content updates work with aria-live regions.",
825				"Live regions are essential for accessible web apps.",
826				"Try this with a screen reader like NVDA or JAWS!"
827			];
828			let nextMessage = 0;
829			let count = 0;
830			const announceBtn = document.getElementById('announce');
831			const liveMessage = document.getElementById('live-message');
832			const contactForm = document.getElementById('contact-form');
833			const emailInput = document.getElementById('email');
834			const messageInput = document.getElementById('message');
835			const messageCount = document.getElementById('message-count');
836			const messageCountStatus = document.getElementById('message-count-status');
837			const formStatus = document.getElementById('form-status');
838			const countDisplay = document.getElementById('count');
839			const countMessage = document.getElementById('count-message');
840			const decreaseBtn = document.getElementById('decrease');
841			const increaseBtn = document.getElementById('increase');
842			const resetBtn = document.getElementById('reset');
843	
844			const updateCountDisplay = () => {
845				countDisplay.textContent = String(count);
846				countMessage.textContent = `Count is ${count}.`;
847			};
848	
849			if (countDisplay && countMessage) {
850				decreaseBtn?.addEventListener('click', () => {
851					count--;
852					updateCountDisplay();
853				});
854	
855				increaseBtn?.addEventListener('click', () => {
856					count++;
857					updateCountDisplay();
858				});
859	
860				resetBtn?.addEventListener('click', () => {
861					count = 0;
862					updateCountDisplay();
863				});
864			}
865	
866			if (announceBtn && liveMessage) {
867				announceBtn.addEventListener('click', () => {
868					liveMessage.textContent = messages[nextMessage];
869					nextMessage = (nextMessage + 1) % messages.length;
870				});
871			}
872	
873			if (contactForm) {
874				const emailError = document.getElementById('email-error');
875				const submitBtn = contactForm.querySelector('button[type="submit"]');
876				const isSending = () => submitBtn.getAttribute('aria-disabled') === 'true';
877	
878				// Set here rather than in the markup so native validation still works without JavaScript.
879				contactForm.noValidate = true;
880	
881				const setFormStatus = (message, state) => {
882					formStatus.textContent = message;
883					if (state) {
884						formStatus.dataset.state = state;
885					} else {
886						delete formStatus.dataset.state;
887					}
888				};
889	
890				const countThresholds = [0, 10, 25, 50, 100];
891				let lastThreshold;
892	
893				const updateMessageCount = () => {
894					if (messageInput && messageCount) {
895						const remaining = messageInput.maxLength - messageInput.value.length;
896						// Match the page language rather than the browser locale.
897						messageCount.textContent = remaining.toLocaleString(htmlElement.lang);
898						// Announce only when a threshold is crossed, not on every keystroke.
899						const threshold = countThresholds.find((limit) => remaining <= limit);
900						if (messageCountStatus && threshold !== lastThreshold) {
901							lastThreshold = threshold;
902							messageCountStatus.textContent = threshold === undefined
903								? ''
904								: `${remaining.toLocaleString(htmlElement.lang)} characters remaining.`;
905						}
906					}
907				};
908	
909				messageInput?.addEventListener('input', updateMessageCount);
910				// Browsers may restore field values on back/forward navigation.
911				window.addEventListener('pageshow', updateMessageCount);
912				updateMessageCount();
913	
914				const setEmailError = (message) => {
915					emailError.textContent = message;
916					if (message) {
917						emailInput.setAttribute('aria-invalid', 'true');
918						emailInput.setAttribute('aria-describedby', 'email-error email-help');
919					} else {
920						emailInput.removeAttribute('aria-invalid');
921						emailInput.setAttribute('aria-describedby', 'email-help');
922					}
923				};
924	
925				const validateEmail = () => {
926					let message = '';
927					if (emailInput.validity.valueMissing) {
928						message = 'Email address is required for us to respond.';
929					} else if (emailInput.validity.typeMismatch) {
930						message = 'Please enter a valid email address, such as name@example.com.';
931					} else if (!emailInput.validity.valid) {
932						message = 'Please enter a valid email address.';
933					}
934					setEmailError(message);
935					return !message;
936				};
937	
938				emailInput.addEventListener('blur', () => {
939					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
940						validateEmail();
941					}
942				});
943	
944				emailInput.addEventListener('input', () => {
945					if (emailInput.hasAttribute('aria-invalid')) {
946						validateEmail();
947					}
948				});
949	
950				contactForm.addEventListener('input', () => {
951					if (!isSending()) {
952						setFormStatus('');
953					}
954				});
955	
956				contactForm.addEventListener('submit', async (event) => {
957					event.preventDefault();
958					if (isSending()) {
959						return;
960					}
961					setFormStatus('');
962					if (!validateEmail()) {
963						setFormStatus('Please correct the errors above before submitting.', 'error');
964						emailInput.focus();
965						return;
966					}
967					const originalText = submitBtn.textContent;
968					submitBtn.setAttribute('aria-disabled', 'true');
969					submitBtn.setAttribute('aria-busy', 'true');
970					submitBtn.textContent = 'Sending…';
971					setFormStatus('Sending your message…', 'pending');
972					emailInput.readOnly = true;
973					if (messageInput) messageInput.readOnly = true;
974					await new Promise(resolve => setTimeout(resolve, 800));
975					emailInput.readOnly = false;
976					if (messageInput) messageInput.readOnly = false;
977					contactForm.reset();
978					setEmailError('');
979					updateMessageCount();
980					submitBtn.removeAttribute('aria-disabled');
981					submitBtn.removeAttribute('aria-busy');
982					submitBtn.textContent = originalText;
983					setFormStatus('Success! Thanks for your message. This is a demo, so nothing was sent.');
984					emailInput.focus();
985				});
986			}
987		</script>
